def modo_vision(tiene_imagen, tiene_texto):
    if tiene_imagen and tiene_texto:
        return "edicion_guiada_por_imagen"
    if tiene_imagen:
        return "interpretar_imagen"
    if tiene_texto:
        return "generar_imagen"
    return "sin_entrada"

casos = [
    (True, True),
    (True, False),
    (False, True),
]

for tiene_imagen, tiene_texto in casos:
    print(f"imagen={tiene_imagen}, texto={tiene_texto} -> {modo_vision(tiene_imagen, tiene_texto)}")
